-- Puntos FourMaster generados automaticamente con geocodificacion Nominatim
-- Ejecutar en Supabase SQL Editor o via: npx prisma db execute --stdin < scripts/fourmaster-puntos.sql

DO $$
DECLARE v_empresa_id TEXT;
BEGIN
  SELECT id INTO v_empresa_id FROM empresas WHERE LOWER(nombre) LIKE '%four%master%' OR LOWER(slug) = 'four-master' LIMIT 1;
  IF v_empresa_id IS NULL THEN RAISE EXCEPTION 'Empresa FourMaster no encontrada'; END IF;

END $$;

